INSERT INTO public."enterprise_evaluations" ("evaluation_id", "assignment_id", "attitude_score", "professionalism_score", "soft_skills_score", "progress_score", "overall_comments", "is_locked", "submitted_at", "created_at") VALUES ('b3fb54a8-9a31-4a69-9f95-02c83f450214', 'f9b16c64-728c-4014-885a-ebd0b73befac', '7.83', '6.24', '7.83', '7.79', 'Thực tập sinh làm việc chuyên nghiệp, hòa đồng với đồng nghiệp và có tư duy giải quyết vấn đề tốt.', TRUE, '2026-06-14T05:54:24.040Z', '2026-06-15T02:25:37.046Z') ON CONFLICT DO NOTHING;
INSERT INTO public."enterprise_evaluations" ("evaluation_id", "assignment_id", "attitude_score", "professionalism_score", "soft_skills_score", "progress_score", "overall_comments", "is_locked", "submitted_at", "created_at") VALUES ('7503912a-4951-46ee-979e-8627141c0172', '797fa790-8eb5-4b9f-bbe4-11aef0ff703e', '8.48', '9.72', '5.85', '8.38', 'Kỹ năng lập trình khá, tuy nhiên cần cải thiện thêm về kỹ năng giao tiếp và làm việc nhóm.', TRUE, '2026-06-14T16:16:21.617Z', '2026-06-15T02:25:37.106Z') ON CONFLICT DO NOTHING;
INSERT INTO public."enterprise_evaluations" ("evaluation_id", "assignment_id", "attitude_score", "professionalism_score", "soft_skills_score", "progress_score", "overall_comments", "is_locked", "submitted_at", "created_at") VALUES ('7edaa15f-278a-4720-8b77-e44b68f44e8a', '8885aad1-ed2e-4723-8eb3-bb1c72f525d9', '6.44', '8.63', '8.76', '7.98', 'Hoàn thành xuất sắc dự án được giao, có tiềm năng phát triển thành nhân viên chính thức.', TRUE, '2026-06-14T22:58:43.155Z', '2026-06-15T02:25:37.278Z') ON CONFLICT DO NOTHING;
INSERT INTO public."enterprise_evaluations" ("evaluation_id", "assignment_id", "attitude_score", "professionalism_score", "soft_skills_score", "progress_score", "overall_comments", "is_locked", "submitted_at", "created_at") VALUES ('a916ee5c-b426-441f-8677-5309c41374fa', '4c6c9854-1127-4ce3-acf9-0ea6e7c04ad5', '9.23', '5.40', '7.95', '5.07', 'Chăm chỉ, chịu khó học hỏi, thái độ làm việc nghiêm túc. Đóng góp nhiều cho team.', TRUE, '2026-06-14T12:28:55.703Z', '2026-06-15T02:25:37.352Z') ON CONFLICT DO NOTHING;
INSERT INTO public."enterprise_evaluations" ("evaluation_id", "assignment_id", "attitude_score", "professionalism_score", "soft_skills_score", "progress_score", "overall_comments", "is_locked", "submitted_at", "created_at") VALUES ('da4f1fff-f932-4680-806a-5422c9197dce', 'b0dff69c-f7df-4589-92e4-22e5d0aa07ec', '5.13', '9.02', '7.49', '5.98', 'Kỹ năng chuyên môn tốt, có khả năng làm việc độc lập. Rất hài lòng với thái độ của sinh viên.', TRUE, '2026-06-14T20:35:04.328Z', '2026-06-15T02:25:37.480Z') ON CONFLICT DO NOTHING;
