INSERT INTO public."incidents" ("incident_id", "assignment_id", "reported_by", "category", "description", "evidence_urls", "status", "resolution_note", "resolved_by", "resolved_at", "created_at", "updated_at") VALUES ('afda49da-d534-4b1e-a42c-89bf77ae6a61', 'b0dff69c-f7df-4589-92e4-22e5d0aa07ec', '88a413cf-980e-42f9-87dc-95054306875c', 'WORKPLACE', 'Hệ thống mạng tại văn phòng bị chập chờn, ảnh hưởng đến tiến độ công việc.', '["https://example.com/evidence1.png"]', 'RESOLVED', 'Đã báo cáo với bộ phận IT, mạng đã được khắc phục và hoạt động ổn định.', '3304c2d4-5f58-47e4-a595-c21eecc37799', '2026-06-14T22:28:59.221Z', '2026-06-15T02:25:37.484Z', '2026-06-15T02:25:37.484Z') ON CONFLICT DO NOTHING;
INSERT INTO public."incidents" ("incident_id", "assignment_id", "reported_by", "category", "description", "evidence_urls", "status", "resolution_note", "resolved_by", "resolved_at", "created_at", "updated_at") VALUES ('9dea39dd-598e-456d-9785-bbcb63d7e01f', '9655f3f8-c125-4b1f-8fdb-deacdfb76717', 'cee3f1a2-fac1-4625-9287-6419b266e829', 'OTHER', 'Xảy ra mâu thuẫn nhỏ giữa các thành viên trong nhóm dự án, cần được hỗ trợ giải quyết.', '["https://example.com/evidence1.png"]', 'RESOLVED', 'Quản lý trực tiếp đã họp mặt các bên, hòa giải thành công và thống nhất cách làm việc.', '3304c2d4-5f58-47e4-a595-c21eecc37799', '2026-06-14T15:22:29.869Z', '2026-06-15T02:25:37.582Z', '2026-06-15T02:25:37.582Z') ON CONFLICT DO NOTHING;
INSERT INTO public."internship_plan_items" ("plan_item_id", "plan_id", "week_number", "task_description", "training_objective", "target_date", "status", "order_index", "created_at", "updated_at") VALUES ('1e07bfd9-ac6b-4649-bf71-0f14d1a83ee8', '29821d58-a1e9-4581-9c92-f58cf71dcd70', 1, 'Tìm hiểu quy trình làm việc, làm quen với môi trường và các công cụ nội bộ.', 'Nắm bắt được văn hóa công ty và cách sử dụng các hệ thống nội bộ.', '2026-09-28T17:00:00.000Z', 'APPROVED', 1, '2026-06-15T02:25:36.892Z', '2026-06-15T02:25:36.892Z') ON CONFLICT DO NOTHING;
INSERT INTO public."internship_plan_items" ("plan_item_id", "plan_id", "week_number", "task_description", "training_objective", "target_date", "status", "order_index", "created_at", "updated_at") VALUES ('8985d05c-2835-4b3e-8a3d-79c1d1180e99', '29821d58-a1e9-4581-9c92-f58cf71dcd70', 2, 'Tham gia dự án thực tế, thực hiện các task nhỏ dưới sự hướng dẫn của mentor.', 'Áp dụng kiến thức học thuật vào môi trường doanh nghiệp thực tế.', '2026-08-09T17:00:00.000Z', 'APPROVED', 2, '2026-06-15T02:25:36.897Z', '2026-06-15T02:25:36.897Z') ON CONFLICT DO NOTHING;
INSERT INTO public."internship_plan_items" ("plan_item_id", "plan_id", "week_number", "task_description", "training_objective", "target_date", "status", "order_index", "created_at", "updated_at") VALUES ('8f5d0829-292d-485a-afee-36308d46a5ed', '29821d58-a1e9-4581-9c92-f58cf71dcd70', 3, 'Tự độc lập giải quyết các vấn đề được giao, phối hợp với các thành viên khác.', 'Cải thiện kỹ năng làm việc nhóm, kỹ năng phân tích và xử lý tình huống.', '2026-08-16T17:00:00.000Z', 'APPROVED', 3, '2026-06-15T02:25:36.903Z', '2026-06-15T02:25:36.903Z') ON CONFLICT DO NOTHING;
INSERT INTO public."internship_plan_items" ("plan_item_id", "plan_id", "week_number", "task_description", "training_objective", "target_date", "status", "order_index", "created_at", "updated_at") VALUES ('b28ee994-079a-4c26-af5b-32b386c571af', '29821d58-a1e9-4581-9c92-f58cf71dcd70', 4, 'Tổng hợp kết quả, báo cáo tiến độ và nghiệm thu các công việc đã làm trong kỳ thực tập.', 'Đánh giá được năng lực bản thân, rút ra kinh nghiệm để chuẩn bị cho công việc sau này.', '2026-11-22T17:00:00.000Z', 'APPROVED', 4, '2026-06-15T02:25:36.911Z', '2026-06-15T02:25:36.911Z') ON CONFLICT DO NOTHING;
