INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('21691fbb-daca-4c58-acfb-372bc670dd65', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Trợ lý Dự án Công nghệ', 'Hỗ trợ lên ý tưởng, viết nội dung và chạy các chiến dịch quảng cáo trên các nền tảng số. Đo lường và báo cáo hiệu quả chiến dịch.', 'Cẩn thận, tỉ mỉ, có khả năng phát hiện lỗi tốt. Ưu tiên các bạn đã học môn Kiểm thử phần mềm.', 'Được tiếp xúc và làm việc với các dự án lớn, học hỏi các quy trình làm việc chuyên nghiệp chuẩn Agile/Scrum.', 'Sinh viên rất chăm chỉ, luôn hoàn thành task trước hạn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('3f383362-d265-492b-ab39-25fb06336251', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Lập trình Web', 'Hỗ trợ thiết kế giao diện người dùng cho các ứng dụng di động và web. Phối hợp với team phát triển để đảm bảo thiết kế được triển khai đúng.', 'Có khả năng sử dụng các công cụ cơ bản, tư duy logic tốt và cẩn thận trong công việc.', 'Được hướng dẫn bởi các anh chị có kinh nghiệm (mentor 1 kèm 1), tham gia các buổi training nội bộ.', 'Kỹ năng chuyên môn tốt, đáp ứng được yêu cầu của dự án.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('87893f78-52a3-4632-b5cf-a6e5fa1db54d', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Chuyên viên Nhân sự Thực tập', 'Cùng đội ngũ kỹ sư tham gia thiết kế, lập trình và kiểm thử các tính năng mới của sản phẩm. Cơ hội làm việc với các công nghệ tiên tiến.', 'Cẩn thận, tỉ mỉ, có khả năng phát hiện lỗi tốt. Ưu tiên các bạn đã học môn Kiểm thử phần mềm.', 'Cẩn thận, tỉ mỉ, có khả năng phát hiện lỗi tốt. Ưu tiên các bạn đã học môn Kiểm thử phần mềm.', 'Học hỏi được nhiều kinh nghiệm thực tế quý báu từ công ty.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('80ca227c-7594-40df-9380-635f0dde2f39', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Backend NodeJS', 'Hỗ trợ lên ý tưởng, viết nội dung và chạy các chiến dịch quảng cáo trên các nền tảng số. Đo lường và báo cáo hiệu quả chiến dịch.', 'Kỹ năng giao tiếp tốt, nhanh nhẹn, hòa đồng và thích làm việc với con người.', 'Trung thực, cẩn thận, nắm vững các nguyên lý kế toán cơ bản.', 'Môi trường làm việc chuyên nghiệp, đồng nghiệp thân thiện.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('853fe0d2-52db-4dfa-94ae-f505eddd0e65', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Trợ lý Dự án Công nghệ', 'Tham gia thiết kế và xây dựng các API backend sử dụng NodeJS. Hỗ trợ tối ưu hóa hiệu suất và bảo mật của hệ thống.', 'Được tiếp xúc và làm việc với các dự án lớn, học hỏi các quy trình làm việc chuyên nghiệp chuẩn Agile/Scrum.', 'Cẩn thận, tỉ mỉ, có khả năng phát hiện lỗi tốt. Ưu tiên các bạn đã học môn Kiểm thử phần mềm.', 'Mong muốn được tham gia nhiều dự án quy mô lớn hơn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('20e31b67-6f1c-4224-b146-cc7fb4d600f6', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Chuyên viên Nhân sự Thực tập', 'Hỗ trợ quản lý dự án, theo dõi tiến độ công việc, và điều phối tài nguyên giữa các nhóm để đảm bảo dự án hoàn thành đúng hạn.', 'Được hỗ trợ phụ cấp thực tập. Có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập.', 'Được hướng dẫn bởi các anh chị có kinh nghiệm (mentor 1 kèm 1), tham gia các buổi training nội bộ.', 'Học hỏi được nhiều kinh nghiệm thực tế quý báu từ công ty.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('565c7614-85ec-4a18-934f-4d9620ae5e03', '4b08d571-1c53-4a3f-97e4-d958a3fa052b', '61689574-efe6-4ea8-abca-4763018ca599', 'Trợ lý Dự án Công nghệ', 'Hỗ trợ tuyển dụng, quản lý hồ sơ ứng viên và tham gia tổ chức các sự kiện nội bộ nhằm gắn kết nhân viên.', 'Môi trường làm việc năng động, trẻ trung. Trà, cà phê và bánh kẹo miễn phí tại văn phòng.', 'Tham gia các hoạt động teambuilding, company trip cùng công ty.', 'Mong muốn được tham gia nhiều dự án quy mô lớn hơn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('01316213-e580-4601-99c2-ce274b26a2d4', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Backend NodeJS', 'Tham gia vào việc phát triển và bảo trì các ứng dụng web nội bộ của công ty. Hỗ trợ team trong việc viết tài liệu kỹ thuật và xử lý lỗi.', 'Được hỗ trợ phụ cấp thực tập. Có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập.', 'Được hướng dẫn bởi các anh chị có kinh nghiệm (mentor 1 kèm 1), tham gia các buổi training nội bộ.', 'Hoàn thành xuất sắc các chỉ tiêu được giao phó.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('8ef1ae20-1b59-433f-bd11-524f2b3bc37a', '4b08d571-1c53-4a3f-97e4-d958a3fa052b', '61689574-efe6-4ea8-abca-4763018ca599', 'Chuyên viên Nhân sự Thực tập', 'Hỗ trợ thiết kế giao diện người dùng cho các ứng dụng di động và web. Phối hợp với team phát triển để đảm bảo thiết kế được triển khai đúng.', 'Kỹ năng tổ chức công việc tốt, biết sử dụng các công cụ quản lý dự án cơ bản như Trello, Jira.', 'Kỹ năng viết tốt, sáng tạo và cập nhật các xu hướng mới trên mạng xã hội.', 'Học hỏi được nhiều kinh nghiệm thực tế quý báu từ công ty.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('8e42cc8d-6ec5-4bc1-ad55-de71b18b276f', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Tester (QC)', 'Hỗ trợ các công việc kế toán hàng ngày như nhập liệu, kiểm tra chứng từ và chuẩn bị báo cáo tài chính.', 'Tham gia các hoạt động teambuilding, company trip cùng công ty.', 'Trung thực, cẩn thận, nắm vững các nguyên lý kế toán cơ bản.', 'Sinh viên rất chăm chỉ, luôn hoàn thành task trước hạn.
