INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('092ebc97-9fde-4c1d-b8a5-85c27cd70dd4', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Chuyên viên Nhân sự Thực tập', 'Hỗ trợ các công việc kế toán hàng ngày như nhập liệu, kiểm tra chứng từ và chuẩn bị báo cáo tài chính.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành liên quan. Có kiến thức nền tảng tốt và thái độ chủ động học hỏi.', 'Được hỗ trợ phụ cấp thực tập. Có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập.', 'Đạt được tiến bộ đáng kể trong tuần này.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('98c0c1aa-61a2-43b1-a932-95e50237fde0', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Lập trình Web', 'Cùng đội ngũ kỹ sư tham gia thiết kế, lập trình và kiểm thử các tính năng mới của sản phẩm. Cơ hội làm việc với các công nghệ tiên tiến.', 'Trung thực, cẩn thận, nắm vững các nguyên lý kế toán cơ bản.', 'Môi trường làm việc năng động, trẻ trung. Trà, cà phê và bánh kẹo miễn phí tại văn phòng.', 'Kỹ năng chuyên môn tốt, đáp ứng được yêu cầu của dự án.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('e29eea76-da73-4481-ab83-f69bd572bb13', '4b08d571-1c53-4a3f-97e4-d958a3fa052b', '61689574-efe6-4ea8-abca-4763018ca599', 'Học hỏi được nhiều kinh nghiệm thực tế quý báu từ công ty.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('ff7f2a3b-70ad-4320-b070-7fdeb5b5b14e', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Tester (QC)', 'Lên kịch bản kiểm thử, thực hiện test các tính năng phần mềm và báo cáo lỗi cho đội ngũ phát triển. Đảm bảo chất lượng sản phẩm.', 'Có khả năng sử dụng các công cụ cơ bản, tư duy logic tốt và cẩn thận trong công việc.', 'Được hướng dẫn bởi các anh chị có kinh nghiệm (mentor 1 kèm 1), tham gia các buổi training nội bộ.', 'Kỹ năng chuyên môn tốt, đáp ứng được yêu cầu của dự án.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('d1f7be51-d703-4e9d-9a89-40117c849218', '4b08d571-1c53-4a3f-97e4-d958a3fa052b', '61689574-efe6-4ea8-abca-4763018ca599', 'Trợ lý Dự án Công nghệ', 'Hỗ trợ lên ý tưởng, viết nội dung và chạy các chiến dịch quảng cáo trên các nền tảng số. Đo lường và báo cáo hiệu quả chiến dịch.', 'Kỹ năng tổ chức công việc tốt, biết sử dụng các công cụ quản lý dự án cơ bản như Trello, Jira.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành liên quan. Có kiến thức nền tảng tốt và thái độ chủ động học hỏi.', 'Mong muốn được tham gia nhiều dự án quy mô lớn hơn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('954fa02a-1ab4-40f2-b2b9-eeeed3f78107', '4b08d571-1c53-4a3f-97e4-d958a3fa052b', '61689574-efe6-4ea8-abca-4763018ca599', 'Trợ lý Dự án Công nghệ', 'Lên kịch bản kiểm thử, thực hiện test các tính năng phần mềm và báo cáo lỗi cho đội ngũ phát triển. Đảm bảo chất lượng sản phẩm.', 'Có gu thẩm mỹ tốt, sử dụng thành thạo Figma hoặc các công cụ thiết kế tương tự.', 'Được hướng dẫn bởi các anh chị có kinh nghiệm (mentor 1 kèm 1), tham gia các buổi training nội bộ.', 'Sinh viên rất chăm chỉ, luôn hoàn thành task trước hạn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('86475d45-f56b-4421-8f7b-b8deff87300a', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Trợ lý Dự án Công nghệ', 'Hỗ trợ quản lý dự án, theo dõi tiến độ công việc, và điều phối tài nguyên giữa các nhóm để đảm bảo dự án hoàn thành đúng hạn.', 'Được hỗ trợ phụ cấp thực tập. Có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập.', 'Trung thực, cẩn thận, nắm vững các nguyên lý kế toán cơ bản.', 'Mong muốn được tham gia nhiều dự án quy mô lớn hơn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('06a45077-aa4d-4fae-99a9-000a48edc15b', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Phân tích Dữ liệu', 'Tham gia thiết kế và xây dựng các API backend sử dụng NodeJS. Hỗ trợ tối ưu hóa hiệu suất và bảo mật của hệ thống.', 'Được hỗ trợ phụ cấp thực tập. Có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập.', 'Được tiếp xúc và làm việc với các dự án lớn, học hỏi các quy trình làm việc chuyên nghiệp chuẩn Agile/Scrum.', 'Học hỏi được nhiều kinh nghiệm thực tế quý báu từ công ty.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('1c02d2bc-a935-4203-8c31-65b3dc87b430', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Phân tích Dữ liệu', 'Hỗ trợ các công việc kế toán hàng ngày như nhập liệu, kiểm tra chứng từ và chuẩn bị báo cáo tài chính.', 'Được hỗ trợ phụ cấp thực tập. Có cơ hội trở thành nhân viên chính thức sau khi kết thúc kỳ thực tập.', 'Có gu thẩm mỹ tốt, sử dụng thành thạo Figma hoặc các công cụ thiết kế tương tự.', 'Sinh viên rất chăm chỉ, luôn hoàn thành task trước hạn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('e335580a-1292-45cc-b146-99e43d451df7', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Kế toán', 'Lên kịch bản kiểm thử, thực hiện test các tính năng phần mềm và báo cáo lỗi cho đội ngũ phát triển. Đảm bảo chất lượng sản phẩm.', 'Đam mê công nghệ, đã từng làm các dự án nhỏ trên lớp hoặc dự án cá nhân. Có tinh thần làm việc nhóm.', 'Môi trường làm việc năng động, trẻ trung. Trà, cà phê và bánh kẹo miễn phí tại văn phòng.', 'Kỹ năng chuyên môn tốt, đáp ứng được yêu cầu của dự án.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('b07735ad-7dec-428e-9b63-0f23937c3cf8', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Marketing Điện tử', 'Hỗ trợ quản lý dự án, theo dõi tiến độ công việc, và điều phối tài nguyên giữa các nhóm để đảm bảo dự án hoàn thành đúng hạn.', 'Tham gia các hoạt động teambuilding, company trip cùng công ty.', 'Sinh viên năm cuối hoặc mới tốt nghiệp các chuyên ngành liên quan. Có kiến thức nền tảng tốt và thái độ chủ động học hỏi.', 'Kỹ năng chuyên môn tốt, đáp ứng được yêu cầu của dự án.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('af62f88b-4abb-4210-a724-b8e3dd6480e4', '4b08d571-1c53-4a3f-97e4-d958a3fa052b', '61689574-efe6-4ea8-abca-4763018ca599', 'Trợ lý Dự án Công nghệ', 'Lên kịch bản kiểm thử, thực hiện test các tính năng phần mềm và báo cáo lỗi cho đội ngũ phát triển. Đảm bảo chất lượng sản phẩm.', 'Kỹ năng giao tiếp tốt, nhanh nhẹn, hòa đồng và thích làm việc với con người.', 'Môi trường làm việc năng động, trẻ trung. Trà, cà phê và bánh kẹo miễn phí tại văn phòng.', 'Sinh viên rất chăm chỉ, luôn hoàn thành task trước hạn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('458ca232-ffcf-4b82-998b-8a809b860404', '7fc76026-7ba5-4493-96ea-3974d7120f31', '61689574-efe6-4ea8-abca-4763018ca599', 'Thực tập sinh Tester (QC)', 'Hỗ trợ thiết kế giao diện người dùng cho các ứng dụng di động và web. Phối hợp với team phát triển để đảm bảo thiết kế được triển khai đúng.', 'Kỹ năng viết tốt, sáng tạo và cập nhật các xu hướng mới trên mạng xã hội.', 'Kỹ năng tổ chức công việc tốt, biết sử dụng các công cụ quản lý dự án cơ bản như Trello, Jira.', 'Mong muốn được tham gia nhiều dự án quy mô lớn hơn.
INSERT INTO public."job_posts" ("job_post_id", "enterprise_id", "semester_id", "title", "description", "requirements", "benefits", "required_technologies", "max_positions", "application_deadline", "status", "created_at", "updated_at", "deleted_at", "positions_count", "required_skills") VALUES ('4372d5ae-77e7-4eaf-974a-b071de9c98f0', '8a068672-36ce-4632-9412-ad9dc92684dc', '61689574-efe6-4ea8-abca-4763018ca599', 'Chuyên viên Nhân sự Thực tập', 'Lên kịch bản kiểm thử, thực hiện test các tính năng phần mềm và báo cáo lỗi cho đội ngũ phát triển. Đảm bảo chất lượng sản phẩm.', 'Có kiến thức cơ bản về NodeJS, RESTful API và cơ sở dữ liệu (SQL hoặc NoSQL).', 'Kỹ năng viết tốt, sáng tạo và cập nhật các xu hướng mới trên mạng xã hội.', 'Có thái độ tích cực, chủ động trong công việc.
